import { addWarrantyProcessController, approveWarrantyController, brandReturnedWarrantyController, cancelWarrantyController, completeWarrantyController, createWarrantyController, getAllWarrantiesController, getMyWarrantyDetailController, getMyWarrantiesController, getWarrantyDetailController, inspectWarrantyController, lookupWarrantyByPhoneController, lookupWarrantyBySerialController, markCustomerDropOffWarrantyController, markPickedUpWarrantyController, receiveWarrantyController, rejectWarrantyController, returnWarrantyController, schedulePickupWarrantyController, scheduleReturnWarrantyController, sendToBrandWarrantyController, startRepairWarrantyController, } from "#controllers/warranty.controller";
import { VerifyToken } from "#middlewares/Auth";
import { CheckRole } from "#middlewares/CheckRole";
import { Validate } from "#middlewares/Validate";
import { addWarrantyProcessSchema, createWarrantySchema, inspectWarrantySchema, repairWarrantySchema, schedulePickupSchema, scheduleReturnSchema, sendToBrandSchema, warrantyNoteSchema, } from "#validations/warranty.validation";
import { Router } from "express";
const router = Router();
router.use(VerifyToken);
router.get("/lookup", CheckRole("CUSTOMER"), lookupWarrantyBySerialController);
router.get("/lookup-phone", CheckRole("CUSTOMER"), lookupWarrantyByPhoneController);
router.post("/", CheckRole("CUSTOMER"), Validate(createWarrantySchema), createWarrantyController);
router.get("/me", CheckRole("CUSTOMER"), getMyWarrantiesController);
router.get("/me/:warrantyId", CheckRole("CUSTOMER"), getMyWarrantyDetailController);
router.get("/", CheckRole("ADMIN", "EMPLOYEE"), getAllWarrantiesController);
router.get("/:warrantyId", CheckRole("ADMIN", "EMPLOYEE"), getWarrantyDetailController);
router.patch("/:warrantyId/approve", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), approveWarrantyController);
router.patch("/:warrantyId/reject", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), rejectWarrantyController);
router.patch("/:warrantyId/customer-drop-off", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), markCustomerDropOffWarrantyController);
router.patch("/:warrantyId/schedule-pickup", CheckRole("EMPLOYEE"), Validate(schedulePickupSchema), schedulePickupWarrantyController);
router.patch("/:warrantyId/picked-up", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), markPickedUpWarrantyController);
router.patch("/:warrantyId/receive", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), receiveWarrantyController);
router.patch("/:warrantyId/inspect", CheckRole("EMPLOYEE"), Validate(inspectWarrantySchema), inspectWarrantyController);
router.patch("/:warrantyId/process", CheckRole("EMPLOYEE"), Validate(addWarrantyProcessSchema), addWarrantyProcessController);
router.patch("/:warrantyId/start-repair", CheckRole("EMPLOYEE"), Validate(repairWarrantySchema), startRepairWarrantyController);
router.patch("/:warrantyId/send-to-brand", CheckRole("EMPLOYEE"), Validate(sendToBrandSchema), sendToBrandWarrantyController);
router.patch("/:warrantyId/brand-returned", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), brandReturnedWarrantyController);
router.patch("/:warrantyId/complete", CheckRole("EMPLOYEE"), Validate(repairWarrantySchema), completeWarrantyController);
router.patch("/:warrantyId/schedule-return", CheckRole("EMPLOYEE"), Validate(scheduleReturnSchema), scheduleReturnWarrantyController);
router.patch("/:warrantyId/return", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), returnWarrantyController);
router.patch("/:warrantyId/cancel", CheckRole("EMPLOYEE"), Validate(warrantyNoteSchema), cancelWarrantyController);
export default router;
